export interface MfeEvent {

  //The name of the event
  //Corresponds to the 'eventName' argument of the functions dispatchMfeEvent and addMfeEventListener
  name: string;

  //The ID of the MFE that fired the event
  //Corresponds to the 'mfeName' argument of the dispatchMfeEvent function.
  sourceMfe: string;

  //The data associated with the event.
  //Corresponds to the 'data' argument of the dispatchMfeEvent function.
  context: any;
}